CProjectile::CProjectile (ASprite* sprite, int anim, const char* diePs, float scale, vector3df pos, vector3df vel, vector3df accel, float damage)
: CGameObject(0)
{
	m_Node = __IRR_SCENE()->addEmptySceneNode(__IRR_SCENE()->getRootSceneNode());
	m_empty = true;
	setPosition(pos);
	m_velocity = vel;
	m_acceleration = accel;
	m_damage = damage;
	m_inst.StartAnim(sprite, anim, 0, 0);
	m_scale = scale;
	m_dead = false;
	m_ps = 0;
	m_diePs = diePs;
	m_antiFireball = false;
	m_antiGriffin = false;
	m_antiIceball = false;
	m_active = false;
	m_touch = new CTouchElement(CTouchElement::Type_AnyTouch, 40);
	m_touch->SetEnabled(false);

	m_isElfArrow = false;
}

CProjectile::CProjectile (const char* ps, const char* diePs, float scale, vector3df pos, vector3df vel, vector3df accel, float damage)
: CGameObject(0)
{
	m_Node = __IRR_SCENE()->addEmptySceneNode(__IRR_SCENE()->getRootSceneNode());
	m_empty = true;
	setPosition(pos);
	m_velocity = vel;
	m_acceleration = accel;
	m_damage = damage;
	m_scale = scale;
	m_dead = false;
	m_diePs = diePs;
	m_antiFireball = false;
	m_antiGriffin = false;
	m_antiIceball = false;
	m_active = false;
	m_touch = new CTouchElement(CTouchElement::Type_AnyTouch, 40);
	m_touch->SetEnabled(false);

	m_ps = AddParticleSystem(ps);
	m_ps->SetScale(m_scale);

	m_isElfArrow = false;
}

CProjectile::CProjectile (const char* mesh, float damage, const char* diePs, float diePsScale)
: CGameObject(0)
{
	m_Node = LoadColladaScene(mesh, true);
	cleanNode(m_Node);

	m_velocity = v3f(0, 0, 0);
	m_acceleration = v3f(0, 0, 0);
	m_damage = damage;
	m_scale = diePsScale;
	m_dead = false;
	m_diePs = diePs;
	m_ps = 0;
	m_empty = false;
	m_antiFireball = false;
	m_antiGriffin = false;
	m_antiIceball = false;
	m_active = false;
	m_touch = new CTouchElement(CTouchElement::Type_AnyTouch, 40);
	m_touch->SetEnabled(false);

	m_isElfArrow = false;
}

CProjectile::~CProjectile ()
{
	m_Node->remove();
	if (!m_empty)
		m_Node->drop();
	delete m_touch;
}

void CProjectile::setActive ()
{
	m_active = true;
}

void CProjectile::update (f32 time)
{
	if (m_dead || !m_active) return;

	m_inst.Update(time);

	m_velocity += m_acceleration * time;
	setPosition(getPosition() + m_velocity * time);

	p2i screenPos = screenFrom3DPos(getAbsolutePosition());
	m_touch->SetScreenCoordinates(screenPos.X - 20, screenPos.Y - 20, 40, 40);

	if (m_touch->IsActive())
	{
		// drag around
		position2di touch;
		m_touch->GetTouchPos_Current(touch.X, touch.Y);
		plane3df targetPlane = CPlayfield::GetInstance()->getFlyingPlane();
		line3df ray = m_SceneManager->getSceneCollisionManager()->getRayFromScreenCoordinates(touch);
		vector3df targetPos;
		targetPlane.getIntersectionWithLine(ray.start, ray.getVector(), targetPos);

		v3f targetDir = (targetPos - getPosition()) / time;
		float maxVelocity = 25.0f;
		if (targetDir.getLength() > maxVelocity)
			targetDir.setLength(maxVelocity);

		m_velocity = targetDir;
		m_acceleration = v3f();
	}

	if (m_touch->IsNowReleased())
	{
		m_acceleration = v3f(0, -9.8f * 2.0f, 0.0f);
	}

	if (m_antiFireball || m_antiGriffin || m_antiIceball)
	{
		if ((m_target - getPosition()).dotProduct(m_velocity) < 0.0f)
		{
			setPosition(m_target);
			onTargetHit();
		}
	}
	else
	{
		if (CPlayfield::GetInstance()->getGroundPlane().classifyPointRelation(getAbsolutePosition()) != ISREL3D_FRONT)
		{
			v3f pos;
			CPlayfield::GetInstance()->getGroundPlane().getIntersectionWithLine(getPosition(), m_velocity, pos);
			setPosition(pos);
			onGroundHit();
		}
		if (CPlayfield::GetInstance()->getCastlePlane().classifyPointRelation(getAbsolutePosition()) != ISREL3D_FRONT)
		{
			v3f pos;
			CPlayfield::GetInstance()->getCastlePlane().getIntersectionWithLine(getPosition(), m_velocity, pos);
			setPosition(pos);
			onCastleHit();
		}
	}

	if (m_ps)
	{
		m_ps->SetPosition(getPosition());
	}
}

void CProjectile::onTargetHit ()
{
	setDead();

	if (m_antiFireball)
		CPlayfield::GetInstance()->getFireball()->elfArrowHit();
	if (m_antiIceball)
		CPlayfield::GetInstance()->getIceball()->elfArrowHit();
	if (m_antiGriffin)
		CPlayfield::GetInstance()->getGriffin()->elfArrowHit();
}

void CProjectile::onGroundHit ()
{
	setDead();
	const TUnitList& units = CPlayfield::GetInstance()->getUnits();
	for (TUnitList::ConstIterator it = units.begin(); it != units.end(); it++)
	{
		CUnit* unit = *it;
		float dist = (unit->getAbsolutePosition() - getPosition()).getLength();
		if (dist < 3.0f && unit->canBeDamagedByShamanBall())
		{
			unit->damageUnit(1000.0f, UDS_Fireball);
			break;
		}
	}
}

void CProjectile::onCastleHit ()
{
	setDead();
	CPlayfield::GetInstance()->getGate()->damageGate(m_damage);
	CPlayfield::GetInstance()->m_damage += m_damage;

	if (!m_isElfArrow)
		__MGR_SOUNDS()->play( SFX_ATTACK_SPELL_IMPACT );
}

bool CProjectile::isDead ()
{
	return m_dead;
}

void CProjectile::setDead ()
{
	if (!m_dead)
	{
		m_dead = true;
		if (m_ps)
		{
			RemoveParticleSystem(m_ps);
			m_ps = 0;
		}
		if (m_diePs)
		{
			ParticleSystem* die = AddParticleSystem(m_diePs);
			die->SetPosition(getPosition());
			die->SetScale(m_scale * 0.02f);
		}

		if (m_antiFireball)
			s_antiFireballArrowShot = false;
		if (m_antiIceball)
			s_antiIceballArrowShot = false;
		if (m_antiGriffin)
			s_antiGriffinArrowShot = false;
	}
}

void CProjectile::reset ()
{
	s_antiFireballArrowShot = false;
	s_antiIceballArrowShot = false;
	s_antiGriffinArrowShot = false;
}

void CProjectile::draw ()
{
	if (m_dead) return;

	m_inst.Draw3D(getPosition(), m_scale);

	if (m_active && m_inst.GetASprite() == 0)
	{
		SMaterial m;
		m.setFlag(EMF_LIGHTING, false);
		m.setThickness(2);
		m.setMaterialType(EMT_TRANSPARENT_ADD_COLOR);
		__IRR_DRIVER()->setTransform(ETS_WORLD, matrix4::EM4CONST_IDENTITY);
		__IRR_DRIVER()->setMaterial(m);
		__IRR_DRIVER()->draw3DLine(m_startPos, getAbsolutePosition(), 0x80707070);
	}
}

bool CProjectile::s_antiFireballArrowShot = false;
bool CProjectile::s_antiIceballArrowShot = false;
bool CProjectile::s_antiGriffinArrowShot = false;

void CProjectile::setAntiFireball (v3f target)
{
	s_antiFireballArrowShot = true;
	m_antiFireball = true;
	m_target = target;
}

void CProjectile::setAntiIceball (v3f target)
{
	s_antiIceballArrowShot = true;
	m_antiIceball = true;
	m_target = target;
}

void CProjectile::setAntiGriffin (v3f target)
{
	s_antiGriffinArrowShot = true;
	m_antiGriffin = true;
	m_target = target;
}

void CProjectile::goElf ()
{
	// detach from elf, attach to scene
	v3f pos = getAbsolutePosition();
	__IRR_SCENE()->getRootSceneNode()->addChild(getSceneNode());
	setPosition(pos);
	v3f scale = getSceneNode()->getScale();
	getSceneNode()->setScale(v3f(1.0f / scale.X, 1.0f / scale.Y, 1.0f / scale.Z));
	setActive();

	v3f dir = (m_antiFireball || m_antiGriffin || m_antiIceball) ? (m_target - pos).normalize() : v3f(1, 0, 0);
	m_velocity = 40.0f * dir;
	getSceneNode()->setRotation(quaternion().rotationFromTo(dir, vector3df(0, 0, 1)));

	m_startPos = pos;

	m_isElfArrow = true;
}

CTouchElement* CProjectile::getTouch ()
{
	return m_touch;
}
